import json, random, subprocess, sys, os, tempfile
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ref import Ref

MAIN = "/app/submission/main.py"


def gen_config(rnd):
    W = rnd.choice([1, 2, 2, 3, 4, 6])
    cfg = {"version": 1,
           "idle_timeout": rnd.choice([0, 1, 2, 3, 5, 10]),
           "packet_limit": rnd.choice([1, 2, 3, 4, 5, 8]),
           "prefix_width": W,
           "rules": [],
           "fallback": None}
    ids = rnd.sample(range(0, 40), rnd.randint(0, 7))
    for rid in ids:
        k = rnd.randint(1, 4)
        rr = []
        for _ in range(k):
            if rnd.random() < 0.25:
                lo, hi = -20, 20
            else:
                lo = rnd.randint(-25, 25)
                hi = min(25, lo + rnd.randint(0, 6))
            rr.append([lo, hi])
        cfg["rules"].append({"id": rid, "class": rnd.randint(0, 65535),
                             "priority": rnd.randint(-5, 5), "ranges": rr})
    def tree(d):
        if d >= 3 or rnd.random() < 0.35:
            return {"class": rnd.randint(0, 65535)}
        return {"feature": rnd.randrange(W), "threshold": rnd.randint(-25, 25),
                "le": tree(d + 1), "gt": tree(d + 1)}
    cfg["fallback"] = tree(0)
    return cfg


def gen_requests(rnd, cfg):
    reqs = []
    t = 0
    open_ids = []
    nid = 0
    npk = 0
    nck = 0
    while npk < rnd.randint(30, 200) and len(reqs) < 400:
        r = rnd.random()
        if r < 0.15 or not open_ids:
            if len(open_ids) < 6:
                fid = nid
                nid += 1
                t += rnd.choice([0, 0, 1, 2, 5])
                reqs.append({"op": "open", "flow": fid, "time": t})
                open_ids.append(fid)
        elif r < 0.6:
            n = rnd.randint(1, 4)
            pk = []
            tt = t
            for _ in range(n):
                tt += rnd.choice([0, 0, 0, 1, 1, 3])
                pk.append({"flow": rnd.choice(open_ids), "time": tt,
                           "source": rnd.randint(0, 1),
                           "length": rnd.choice([1, 2, 3, 5, 10, 15, 20, 21, 25, 30])})
                npk += 1
            t = tt
            reqs.append({"op": "chunk", "packets": pk})
        elif r < 0.75:
            t += rnd.choice([0, 1, 2, 4, 8, 20])
            reqs.append({"op": "tick", "time": t})
        elif r < 0.85:
            fid = rnd.choice(open_ids)
            t += rnd.choice([0, 0, 1, 3])
            reqs.append({"op": "close", "flow": fid, "time": t})
            open_ids.remove(fid)
        else:
            if nck < 2:
                nck += 1
                reqs.append({"op": "checkpoint"})
            else:
                t += 1
                reqs.append({"op": "tick", "time": t})
    while open_ids:
        fid = open_ids.pop()
        t += rnd.choice([0, 1, 4])
        reqs.append({"op": "close", "flow": fid, "time": t})
    return reqs


def compile_prog(cfg, d):
    p = subprocess.run([sys.executable, "-I", MAIN, "compile"],
                       input=json.dumps(cfg).encode(), stdout=subprocess.PIPE)
    assert p.returncode == 0, (p.returncode, p.stdout)
    path = os.path.join(d, "prog.json")
    with open(path, "wb") as fh:
        fh.write(p.stdout)
    return path


class Stream:
    def __init__(self, d):
        self.p = subprocess.Popen([sys.executable, "-I", MAIN, "stream", d],
                                  stdin=subprocess.PIPE, stdout=subprocess.PIPE)
    def send(self, r):
        self.p.stdin.write(json.dumps(r).encode() + b"\n")
        self.p.stdin.flush()
        return json.loads(self.p.stdout.readline())
    def close(self):
        self.p.stdin.close()
        return self.p.wait()


def run_case(seed, verbose=False):
    rnd = random.Random(seed)
    cfg = gen_config(rnd)
    reqs = gen_requests(rnd, cfg)
    ref = Ref(cfg)
    exp = []
    ckpts = []
    for i, r in enumerate(reqs):
        out = ref.handle(r)
        if "checkpoint" in out:
            ckpts.append((i, out["checkpoint"]))
            exp.append(None)
        else:
            exp.append(out)
    with tempfile.TemporaryDirectory(dir="/workspace/tmp") as d:
        prog = compile_prog(cfg, d)
        a = Stream(prog)
        got = []
        snaps = {}
        for i, r in enumerate(reqs):
            resp = a.send(r)
            if "checkpoint" in resp:
                assert set(resp) == {"checkpoint"} and isinstance(resp["checkpoint"], dict)
                snaps[i] = resp["checkpoint"]
                got.append(None)
            else:
                assert set(resp) == {"events"}, resp
                got.append(resp)
        rc = a.close()
        assert rc == 0, rc
        for i, r in enumerate(reqs):
            if exp[i] is not None:
                assert got[i] == exp[i], (seed, cfg, i, r, got[i], exp[i])
        # restart test at each captured checkpoint
        for i, r in enumerate(reqs):
            if exp[i] is None:
                b = Stream(prog)
                assert b.send({"op": "restore", "checkpoint": snaps[i]}) == {"events": []}
                for j in range(i + 1, len(reqs)):
                    resp = b.send(reqs[j])
                    if exp[j] is None:
                        # nested checkpoint must also behave identically
                        assert set(resp) == {"checkpoint"}
                        assert resp["checkpoint"] == snaps[j], (seed, j)
                    else:
                        assert resp == exp[j], (seed, cfg, j, reqs[j], resp, exp[j])
                assert b.close() == 0
    return True


if __name__ == "__main__":
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 100
    start = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    for s in range(start, start + n):
        run_case(s)
        if (s - start + 1) % 10 == 0:
            print("ok", s + 1, flush=True)
    print("ALL PASS")
